  const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();
  let room=null,reader=null,lease=null,phase='closed',transition=null,bookProgress=0,dirty=false,dead=false,generation=0,pressed=null,returnFocus=null,pendingBook=false,rememberedChapter=0,placesOpen=false,placesInert=[],photoHeaderInert=false,renderedFrames=0,viewport=null;
