  function escape(){if(placesOpen)return hidePlaces();if(reader?.isOpen)return reader.cancel();if(phase==='book-opening')return beginBookClose();if(phase==='book-closing'||phase==='returning')return false;return close();}
  listen(q('[data-about-open]'),'click',openBook);listen(q('[data-about-exit]'),'click',()=>close());listen(q('[data-about-retry]'),'click',loadPortrait);listen(q('[data-about-places]'),'click',showPlaces);listen(q('[data-about-places-close]'),'click',()=>hidePlaces());
