  listen(window,'resize',resize);listen(window,'pagehide',()=>close({immediate:true,notify:false}));listen(media,'change',()=>{if(!reduced()||!transition)return;const task=transition;if(task.kind==='exit')finishClose(task.notify);else if(task.kind==='book'){if(task.to===1)finishBookOpen();else finishBookClose();}else{transition=null;veil.style.opacity='0';setPhase('studio');if(pendingBook)openBook();}});
